window.piDownloadAccountantXls = function () {
  var month = monthVal();
  window.open('/api/platform-invoices/accountant-xls?month=' + encodeURIComponent(month), '_blank');
};
window.piRenderAccountantCards = async function () {
  var box = document.getElementById('pi-accountant-cards');
  if (!box) return;
  try {
    var j = await fetch('/api/platform-invoices/accountants').then(function (r) { return r.json(); });
    var cards = (j && j.accountants) || [];
    if (!cards.length) { box.innerHTML = '<div style="color:var(--tx3)">No accountant cards yet.</div>'; return; }
    box.innerHTML = cards.map(function (c, i) {
      return '<div class="pi-acct-card" data-i="' + i + '" style="border:1px solid var(--bdr);border-radius:10px;padding:10px 12px;margin-bottom:8px;background:var(--bg)">' +
        '<div style="font-weight:600;margin-bottom:6px">' + (c.name || c.email) + '</div>' +
        '<label style="display:block;font-size:12px;margin-bottom:4px">Email <input data-f="email" value="' + String(c.email || '').replace(/"/g, '&quot;') + '" style="width:100%;margin-top:2px"></label>' +
        '<label style="margin-right:12px;font-size:12px"><input type="checkbox" data-f="receivePdfs"' + (c.receivePdfs ? ' checked' : '') + '> PDFs</label>' +
        '<label style="font-size:12px"><input type="checkbox" data-f="receiveExcel"' + (c.receiveExcel ? ' checked' : '') + '> Excel</label>' +
        '<input type="hidden" data-f="id" value="' + String(c.id || '') + '">' +
        '<input type="hidden" data-f="name" value="' + String(c.name || '').replace(/"/g, '&quot;') + '">' +
      '</div>';
    }).join('') + '<button class="btn sm" onclick="piSaveAccountantCards()">Save accountant cards</button>';
  } catch (e) { box.innerHTML = '<div style="color:#b00">' + (e.message || e) + '</div>'; }
};
window.piSaveAccountantCards = async function () {
  var box = document.getElementById('pi-accountant-cards');
  if (!box) return;
  var cards = [];
  box.querySelectorAll('.pi-acct-card').forEach(function (el) {
    var get = function (f) { var n = el.querySelector('[data-f="' + f + '"]'); return n ? n.value : ''; };
    var chk = function (f) { var n = el.querySelector('[data-f="' + f + '"]'); return !!(n && n.checked); };
    cards.push({ id: get('id'), name: get('name') || get('email'), email: get('email'), receivePdfs: chk('receivePdfs'), receiveExcel: chk('receiveExcel') });
  });
  msg('Saving accountant cards…', true);
  try {
    var res = await fetch('/api/platform-invoices/accountants', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ accountants: cards }) });
    var j = await res.json();
    if (!res.ok) throw new Error((j && j.error) || 'save failed');
    msg('Accountant cards saved', true);
    await piRenderAccountantCards();
  } catch (e) { msg(e.message || String(e), false); }
};
window.piLoadAgentLatest = async function () {
  var box = document.getElementById('pi-agent-report');
  if (!box) return;
  try {
    var j = await fetch('/api/platform-invoices/agent/latest').then(function (r) { return r.json(); });
    var r = j && j.report;
    if (!r) { box.textContent = ''; return; }
    box.innerHTML = '<b>Last agent</b> ' + (r.month || '') + ' · ' + (r.status || '') +
      ' · Excel ' + ((r.excel && r.excel.totalRows) || 0) + ' rows' +
      ' · emailed ' + ((r.emailed && r.emailed.length) || 0) +
      ((r.booking && r.booking.errors && r.booking.errors.length) ? (' · Booking errors ' + r.booking.errors.length) : '');
  } catch (e) {}
};
window.piRunAgent = async function () {
  var month = monthVal();
  var btn = document.getElementById('pi-agent-btn');
  if (btn) btn.disabled = true;
  msg('Running Platform Invoices agent for ' + month + '…', true);
  try {
    var res = await fetch('/api/platform-invoices/agent', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ month: month, send: true }) });
    var j = await res.json();
    if (!res.ok) throw new Error((j && j.error) || 'agent failed');
    var id = j.job && j.job.id;
    var deadline = Date.now() + 95 * 60 * 1000;
    while (id && Date.now() < deadline) {
      await new Promise(function (r) { setTimeout(r, 1500); });
      var st = await fetch('/api/platform-invoices/agent/' + encodeURIComponent(id)).then(function (r) { return r.json(); });
      var job = st && st.job;
      if (!job) break;
      if (job.hint) msg(job.hint, true);
      if (job.status === 'done' || job.status === 'error') {
        if (job.error) throw new Error(job.error);
        var rep = job.report || {};
        msg('Agent ' + (rep.status || 'done') + ' · Excel rows ' + ((rep.excel && rep.excel.totalRows) || 0) +
          ((rep.booking && rep.booking.errors && rep.booking.errors.length) ? (' · blocked: ' + rep.booking.errors.length + ' Booking error(s)') : ''),
          rep.status !== 'blocked' && rep.status !== 'error');
        await piLoadAgentLatest();
        break;
      }
    }
  } catch (e) { msg(e.message || String(e), false); }
  if (btn) btn.disabled = false;
};
